import openpyxl

# Load data
wb = openpyxl.load_workbook('/root/data.xlsx', data_only=True)
ws = wb['Data']

# Parse turns
games = {}  # game_number -> list of (turn_num, rolls)

for row in ws.iter_rows(min_row=10, max_row=6009, values_only=True):
    turn_num = row[2]
    game_num = row[3]
    rolls = list(row[4:10])

    if turn_num is None:
        continue

    if game_num not in games:
        games[game_num] = []
    games[game_num].append((turn_num, rolls))

print(f"Total games: {len(games)}")

# Scoring functions
def score_high_and_often(rolls):
    highest = max(rolls)
    count = rolls.count(highest)
    return highest * count

def score_summation(rolls):
    return sum(rolls)

def score_highs_and_lows(rolls):
    highest = max(rolls)
    lowest = min(rolls)
    return highest * lowest * (highest - lowest)

def score_only_two_numbers(rolls):
    if len(set(rolls)) == 2:
        return 30
    return 0

def score_all_the_numbers(rolls):
    if sorted(rolls) == [1, 2, 3, 4, 5, 6]:
        return 40
    return 0

def score_ordered(rolls):
    if len(rolls) < 4:
        return 0
    for i in range(len(rolls) - 3):
        subset = rolls[i:i+4]
        increasing = all(subset[j+1] == subset[j] + 1 for j in range(3))
        decreasing = all(subset[j+1] == subset[j] - 1 for j in range(3))
        if increasing or decreasing:
            return 50
    return 0

CATEGORIES = ['high_and_often', 'summation', 'highs_and_lows', 'only_two', 'all_numbers', 'ordered']

def get_scores(rolls):
    return {
        'high_and_often': score_high_and_often(rolls),
        'summation': score_summation(rolls),
        'highs_and_lows': score_highs_and_lows(rolls),
        'only_two': score_only_two_numbers(rolls),
        'all_numbers': score_all_the_numbers(rolls),
        'ordered': score_ordered(rolls),
    }

def best_game_score(turn1_scores, turn2_scores):
    best = 0
    for i, cat1 in enumerate(CATEGORIES):
        for j, cat2 in enumerate(CATEGORIES):
            if i == j:
                continue
            total = turn1_scores[cat1] + turn2_scores[cat2]
            if total > best:
                best = total
    return best

def best_single_turn_score(turn_scores):
    """For a game with only one turn, best score is max of any single category"""
    return max(turn_scores.values())

# Calculate game scores
game_scores = {}
for game_num in sorted(games.keys()):
    turn_list = games[game_num]

    if len(turn_list) == 2:
        t1_rolls = turn_list[0][1]
        t2_rolls = turn_list[1][1]
        t1_scores = get_scores(t1_rolls)
        t2_scores = get_scores(t2_rolls)
        score = best_game_score(t1_scores, t2_scores)
    elif len(turn_list) == 1:
        t_scores = get_scores(turn_list[0][1])
        score = best_single_turn_score(t_scores)
        print(f"Game {game_num} has only 1 turn, score: {score}")
    else:
        print(f"WARNING: Game {game_num} has {len(turn_list)} turns!")
        continue

    game_scores[game_num] = score

# Verify first few games
print(f"\nFirst 10 game scores:")
for g in range(1, 11):
    print(f"  Game {g}: score={game_scores[g]}")

# Player matching: odd games = Player 1, even games = Player 2
# Matches: game 1 vs 2, game 3 vs 4, etc.
player1_wins = 0
player2_wins = 0
draws = 0

for i in range(1, 3000, 2):
    p1_game = i      # odd
    p2_game = i + 1   # even

    p1_score = game_scores[p1_game]
    p2_score = game_scores[p2_game]

    if p1_score > p2_score:
        player1_wins += 1
    elif p2_score > p1_score:
        player2_wins += 1
    else:
        draws += 1

print(f"\nPlayer 1 wins: {player1_wins}")
print(f"Player 2 wins: {player2_wins}")
print(f"Draws: {draws}")
answer = player1_wins - player2_wins
print(f"Answer (P1 wins - P2 wins): {answer}")

with open('/root/answer.txt', 'w') as f:
    f.write(str(answer))

print("\nAnswer written to /root/answer.txt")
